package main

import "cmp"

func add(a, b int) int {
	return a + b
}

// clamp returns v constrained to the inclusive range [lo, hi].
func clamp[T cmp.Ordered](v, lo, hi T) T {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

// Clamp is the exported form of clamp.
func Clamp[T cmp.Ordered](v, lo, hi T) T {
	return clamp(v, lo, hi)
}

func main() {}

